/** Markdown overview of the whole structure for AI tools; pure rendering, no Obsidian access. */
import { compare_text } from './collate';
import { child_entries, describe_note, type StructureIndex, type TreeEntry } from './structure_index';

/** Paths of the generated files inside the shared AI folder (see the `aiFolder` setting). */
export const STRUCTURE_EXPORT_NAME = 'moc-tree/structure.md';
export const NOTES_EXPORT_NAME = 'moc-tree/notes.md';

/** Settings the explanation needs. */
export interface ExportContext {
	/** Managed folders; `''` stands for the whole vault. */
	folders: readonly string[];
	/** Folder for new notes; notes directly inside are written by file name only. */
	inbox: string;
	structure_key: string;
	trash_tag: string;
}

/** Generated files: vault-relative name below the AI folder → content. */
export type ExportFiles = ReadonlyMap<string, string>;

/** Inline code span that survives backticks in the text. */
function code(text: string): string {
	return text.includes('`') ? `\`\` ${text} \`\`` : `\`${text}\``;
}

/** Text safe for one table cell. */
function cell(text: string): string {
	return text.replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ');
}

/** True if the note lies directly in the inbox, so its path follows from the file name. */
function in_inbox(path: string, basename: string, inbox: string): boolean {
	return path === (inbox === '' ? `${basename}.md` : `${inbox}/${basename}.md`);
}

/** Label of the inbox for explanations. */
function inbox_label(inbox: string): string {
	return inbox === '' ? 'the vault root' : code(inbox);
}

/** Explanation of the note format, so the file is readable without knowing the plugin. */
function render_intro(ctx: ExportContext): string[] {
	const folders = ctx.folders.map((folder) => (folder === '' ? '(whole vault)' : code(folder))).join(', ');
	const key = code(ctx.structure_key);
	return [
		'# MOC Tree structure',
		'',
		'Generated by the Obsidian plugin MOC Tree from the notes\' frontmatter and rewritten whenever the',
		'structure changes. Do not edit this file; the notes themselves are the only source of truth.',
		'It shows the folder tree; single notes are in `notes.md` (next to it), search there by title or',
		'file name.',
		'',
		'## How the notes are organized',
		'',
		`- Managed folders (recursive): ${folders}. Every Markdown note there is a managed note.`,
		'- Each note has a `title` (its display name) and `aliases` (title plus synonyms). File names are',
		'  usually timestamps without meaning. A link like `[[2026111009123048]]` points to a file name;',
		'  look up its title in `notes.md`.',
		`- A note with the property ${key} is a folder note (MOC). ${key} lists its entries in order,`,
		'  one wiki link per line. Folders contain notes and further folders; a note can be in several',
		'  folders. There are no real directories for this structure.',
		`- Links in the note text are cross-references, never structure. Only ${key} defines the tree.`,
		`- Notes tagged ${code(`#${ctx.trash_tag}`)} are in the trash; they keep their place in ${key}.`,
		'- Notes outside the managed folders appear only if a folder note links them.',
		'',
	];
}

/** Explanation above the tree. */
function tree_help(ctx: ExportContext): string {
	return (
		'Only folder notes, indented by depth, in the order of the folder lists. Each line:\n' +
		'title — file [markers] (number of notes directly inside). The notes themselves are listed in\n' +
		'`notes.md`: search its "Folders" column for the folder\'s file name.\n' +
		`A bare file name like \`2026111009123048\` means \`${ctx.inbox === '' ? '' : `${ctx.inbox}/`}2026111009123048.md\`` +
		` (folder for new notes: ${inbox_label(ctx.inbox)});\n` +
		'other notes are given with their full path. A folder in several folders appears in each of them.'
	);
}

/** Marker suffix for one tree row; folders are already marked by bold text. */
function markers(entry: TreeEntry): string {
	const parts: string[] = [];
	if (entry.kind === 'dead') parts.push('not found');
	if (entry.kind === 'cycle') parts.push('contains itself, not expanded');
	if (entry.outside && entry.kind !== 'dead') parts.push('outside managed folders');
	if (entry.missing_title) parts.push('no title');
	if (entry.parent_count > 1) parts.push(`in ${entry.parent_count} folders`);
	return parts.length > 0 ? ` [${parts.join(', ')}]` : '';
}

/** Renders tree sections; folders expanded once are referenced afterwards to keep the size linear. */
class TreeWriter {
	readonly lines: string[] = [];
	private readonly expanded = new Set<string>();

	/** True while writing the tree section: plain notes are left out and counted instead. */
	private folders_only = false;

	constructor(
		private readonly index: StructureIndex,
		private readonly inbox: string,
	) {}

	/** Short reference to a tree entry: file name for inbox notes, else the path or the dead link. */
	private target(entry: TreeEntry): string {
		if (entry.path === null) return code(`[[${entry.link}]]`);
		const basename = this.index.notes.get(entry.path)?.basename;
		if (basename !== undefined && in_inbox(entry.path, basename, this.inbox)) return code(basename);
		return code(entry.path);
	}

	/** Write one entry and, for folders, its entries below. */
	entry(entry: TreeEntry, depth: number, chain: readonly string[], in_trash: boolean): void {
		const indent = '  '.repeat(depth);
		const name = entry.kind === 'moc' ? `**${entry.name}**` : entry.name;
		const path = entry.path;
		const repeat = entry.kind === 'moc' && path !== null && this.expanded.has(path);
		const row = this.lines.length;
		this.lines.push(`${indent}- ${name} — ${this.target(entry)}${markers(entry)}`);
		if (repeat) this.lines[row] += ' (entries listed above)';
		if (entry.kind !== 'moc' || path === null || repeat) return;
		this.expanded.add(path);
		const next = [...chain, path];
		let notes = 0;
		for (const child of child_entries(this.index, path, new Set(next), in_trash)) {
			if (this.folders_only && child.kind === 'note') notes++;
			else this.entry(child, depth + 1, next, in_trash);
		}
		if (notes > 0) this.lines[row] += notes === 1 ? ' (1 note)' : ` (${notes} notes)`;
	}

	/** Write a section with its top-level paths; `empty` is shown if there are none. */
	section(
		heading: string,
		help: string,
		paths: readonly string[],
		empty: string,
		{ in_trash = false, folders_only = false } = {},
	): void {
		this.folders_only = folders_only;
		this.lines.push(`## ${heading}`, '', help, '');
		if (paths.length === 0) this.lines.push(empty);
		for (const path of paths) this.entry(describe_note(this.index, path), 0, [], in_trash);
		this.lines.push('');
	}
}

/** Lookup table of all known notes: file name, title, aliases, folders, path if not in the inbox. */
function render_notes(index: StructureIndex, ctx: ExportContext): string {
	const lines = [
		'# MOC Tree notes',
		'',
		'Generated by the Obsidian plugin MOC Tree; do not edit. All notes with their folders; the folder',
		'tree is in `structure.md` (next to this file). Search this table for a file name or title instead',
		'of reading it whole.',
		'',
		'- "Aliases": synonyms besides the title.',
		'- "Folders": file names of the folder notes that contain the note. Search for a folder\'s file name',
		'  to list its notes.',
		`- "Path": only if the note is not directly in the folder for new notes (${inbox_label(ctx.inbox)}).`,
		'',
		'| File name | Title | Aliases | Folders | Path |',
		'| --- | --- | --- | --- | --- |',
	];
	const notes = [...index.notes.values()].sort((a, b) => compare_text(a.path, b.path));
	for (const note of notes) {
		// Sorted: the index keeps file listing order, which differs between platforms.
		const parents = (index.parents.get(note.path) ?? [])
			.map((p) => index.notes.get(p)?.basename ?? p)
			.sort(compare_text);
		const flags = [note.children ? 'folder' : '', note.trashed ? 'trash' : '', note.managed ? '' : 'outside']
			.filter((flag) => flag !== '')
			.join(', ');
		const title = note.title ?? '(no title)';
		const aliases = note.aliases.filter((alias) => alias !== note.title);
		const path = in_inbox(note.path, note.basename, ctx.inbox) ? '' : note.path;
		const row = [note.basename, flags ? `${title} [${flags}]` : title, aliases.join(', '), parents.join(', '), path];
		lines.push(`| ${row.map(cell).join(' | ')} |`);
	}
	lines.push('');
	return lines.join('\n');
}

/** Complete file contents; identical input gives identical output (no timestamps). */
export function render_structure_export(index: StructureIndex, ctx: ExportContext): ExportFiles {
	const tree = new TreeWriter(index, ctx.inbox);
	tree.section('Tree', tree_help(ctx), index.roots, '(no folder notes yet)', { folders_only: true });
	tree.section('Orphans', 'Managed notes that are in no folder.', index.orphans, '(none)');
	tree.section('Trash', 'Trashed notes with their entries.', index.trash, '(empty)', { in_trash: true });
	return new Map([
		[STRUCTURE_EXPORT_NAME, [...render_intro(ctx), ...tree.lines].join('\n')],
		[NOTES_EXPORT_NAME, render_notes(index, ctx)],
	]);
}
